insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 22, 'Por acaso eu disse: Trazei-me [algo] ? Ou: Dai presente a mim de vossa riqueza?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 23, 'Ou: Livrai-me da mão do opressor? Ou: Resgatai-me das mãos dos violentos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 24, 'Ensinai-me, e eu [me] calarei; e fazei-me entender em que errei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 25, 'Como são fortes as palavras de boa razão! Mas o que vossa repreensão reprova?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 26, 'Pretendeis repreender palavras, sendo que os argumentos do desesperado são como o vento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 27, 'De fato vós lançaríeis [sortes] sobre o órfão, e venderíeis vosso amigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 28, 'Agora, pois, disponde-vos a olhar para mim; e [vede] se eu minto diante de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 29, 'Mudai de opinião, pois, e não haja perversidade; mudai de opinião, pois minha justiça continua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 6, 30, 'Há perversidade em minha língua? Não poderia meu paladar discernir as coisas más?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 1, 'Por acaso o ser humano não tem um trabalho duro sobre a terra, e não são seus dias como os dias de um assalariado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 2, 'Como o servo suspira pela sombra, e como o assalariado espera por seu pagamento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 3, 'Assim também me deram por herança meses inúteis, e me prepararam noites de sofrimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 4, 'Quando eu me deito, pergunto: Quando me levantarei? Mas a noite se prolonga, e me canso de me virar [na cama] até o amanhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 5, 'Minha carne está coberta de vermes e de crostas de pó; meu pele está rachada e horrível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 6, 'Meus dias são mais rápidos que a lançadeira do tecelão, e perecem sem esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 7, 'Lembra-te que minha vida é um sopro; meus olhos não voltarão a ver o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 8, 'Os olhos dos que me veem não me verão mais; teus olhos estarão sobre mim, porém deixarei de existir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 9, 'A nuvem se esvaece, e passa; assim também quem desce ao Xeol nunca voltará a subir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 10, 'Nunca mais voltará à sua casa, nem seu lugar o conhecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 11, 'Por isso eu não calarei minha boca; falarei na angústia do meu espírito, e me queixarei na amargura de minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 12, 'Por acaso sou eu o mar, ou um monstro marinho, para que me ponhas guarda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 13, 'Quando eu digo: Minha cama me consolará; meu leito aliviará minhas queixa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 14, 'Então tu me espantas com sonhos, e me assombras com visões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 15, 'Por isso minha alma preferia a asfixia [e] a morte, mais que meus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 16, 'Odeio [a minha vida] ; não viverei para sempre; deixa-me, pois que meus dias são inúteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 17, 'O que é o ser humano, para que tanto o estimes, e ponhas sobre ele teu coração,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 18, 'E o visites a cada manhã, e a cada momento o proves?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 19, 'Até quando não me deixarás, nem me liberarás até que eu engula minha saliva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 20, 'Se pequei, o eu que te fiz, ó Guarda dos homens? Por que me fizeste de alvo de dardos, para que eu seja pesado para mim mesmo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 7, 21, 'E por que não perdoas minha transgressão, e tiras minha maldade? Porque agora dormirei no pó, e me buscarás de manhã, porém não mais existirei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 1, 'Então Bildade, o suíta, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 2, 'Até quando falarás tais coisas, e as palavras de tua boca serão como um vento impetuoso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 3, 'Por acaso Deus perverteria o direito, ou o Todo-Poderoso perverteria a justiça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 4, 'Se teus filhos pecaram contra ele, ele também os entregou ao castigo por sua transgressão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 5, 'Se tu buscares a Deus com empenho, e pedires misericórdia ao Todo-Poderoso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 6, 'Se fores puro e correto, certamente logo ele se levantará em teu favor, e restaurará a morada de tua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 7, 'Ainda que teu princípio seja pequeno, o teu fim será muito grandioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 8, 'Pois pergunta agora à geração passada, e considera o que seus pais descobriram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 9, 'Pois nós somos de ontem e nada sabemos, pois nossos dias sobre a terra são como a sombra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 10, 'Por acaso eles não te ensinarão, e te dirão, e falarão palavras de seu coração?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 11, 'Pode o papiro crescer sem lodo? Ou pode o junco ficar maior sem água?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 12, 'Estando ele ainda verde, sem ter sido cortado, ainda assim se seca antes de toda erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 13, 'Assim são os caminhos de todos os que esquecem de Deus; e a esperança do corrupto perecerá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 14, 'Sua esperança será frustrada, e sua confiança será como a teia de aranha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 15, 'Ele se apoiará em sua casa, mas ela não ficará firme; ele se apegará a ela, mas ela não ficará de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 16, 'Ele está bem regado diante do sol, e seus ramos brotam por cima de sua horta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 17, 'Suas raízes se entrelaçam junto à fonte, olhando para o pedregal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 18, 'Se lhe arrancarem de seu lugar, este o negará, [dizendo] : Nunca te vi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 19, 'Eis que este é o prazer de seu caminho; e do solo outros brotarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 20, 'Eis que Deus não rejeita ao íntegro, nem segura pela mão aos malfeitores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 21, 'Ainda ele encherá tua boca de riso, e teus lábios de júbilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 8, 22, 'Os que te odeiam se vestirão de vergonha, e nunca mais haverá tenda de perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 1, 'Mas Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 2, 'Na verdade sei que é assim; mas como pode o ser humano ser justo diante de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 3, 'Ainda se quisesse disputar com ele, não conseguiria lhe responder uma coisa sequer em mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 4, 'Ele é sábio de coração, e poderoso em forças. Quem se endureceu contra ele, e teve paz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 5, 'Ele transporta as montanhas sem que o saibam; e as transtorna em seu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 6, 'Ele remove a terra de seu lugar, e faz suas colunas tremerem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 7, 'Ele dá ordem ao sol, e ele não brilha; e sela as estrelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 8, 'Ele é o que sozinho estende os céus, e anda sobre as alturas do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 9, 'Ele é o que fez a Usra, o Órion, as Plêiades, e as constelações do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 10, 'Ele é o que faz coisas grandes e incompreensíveis, e inúmeras maravilhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 11, 'Eis que ele passa diante de mim, sem que eu não o veja; ele passará diante de mim, sem que eu saiba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 12, 'Eis que, quando ele toma, quem pode lhe impedir? Quem poderá lhe dizer: O que estás fazendo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 13, 'Deus não reverterá sua ira, e debaixo dele se encurvam os assistentes de Raabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 14, 'Como poderia eu lhe responder, e escolher minhas palavras contra ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 15, 'A ele, ainda que eu fosse justo, não lhe responderia; a meu juiz pediria misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 16, 'Ainda que eu lhe chamasse, e ele respondesse, mesmo assim não creria que ele tivesse dado ouvidos à minha voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 17, 'Pois ele tem me quebrantado com tempestade, e multiplicado minhas feridas sem causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 18, 'Ele não me permite respirar; em vez disso, me farta de amarguras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 19, 'Quanto às forças, eis que ele é forte; e quanto ao juízo, [ele diria] : Quem me convocará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 20, 'Ainda que eu seja justo, minha boca me condenaria; se eu fosse inocente, então ela me declararia perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 21, 'Mesmo se eu for inocente, não estimo minha alma; desprezo minha vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 22, 'É tudo a mesma coisa; por isso digo: ele consome ao inocente e ao perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 23, 'Quando o açoite mata de repente, ele ri do desespero dos inocentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 24, 'A terra está entregue nas mãos dos perversos. Ele cobre o rosto de seus juízes. Se não é ele, então quem é?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 25, 'Meus dias foram mais rápidos que um homem que corre; fugiram, e não viram o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 26, 'Passaram como barcos de papiro, como a águia que se lança à comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 27, 'Se disser: Esquecerei minha queixa, mudarei o aspecto do meu rosto, e sorrirei,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 28, '[Ainda] teria pavor de todas as minhas dores; [pois] sei que não me terás por inocente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 29, 'Se eu já estou condenado, então para que eu sofreria em vão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 30, 'Ainda que me lave com água de neve, e limpe minhas mãos com sabão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 31, 'Então me submergirias no fosso, e minhas próprias vestes me abominariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 32, 'Pois ele não é homem como eu, para que eu lhe responda, e venhamos juntamente a juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 33, 'Não há entre nós árbitro que ponha sua mão sobre nós ambos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 34, 'Tire de sobre mim sua vara, e seu terror não me espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 9, 35, '[Então] eu falaria, e não teria medo dele. Pois não está sendo assim comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 1, 'Minha alma está cansada de minha vida. Darei liberdade à minha queixa sobre mim; falarei com amargura de minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 2, 'Direi a Deus: Não me condenes; faz-me saber por que brigas comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 3, '[Parece] -te bem que [me] oprimas, que rejeites o trabalho de tuas mãos, e favoreças o conselho dos perversos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 4, 'Tens tu olhos de carne? Vês tu como o ser humano vê?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 5, 'São teus dias como os dias do ser humano, ou teus anos como os anos do homem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 6, 'Para que investigues minha perversidade, e pesquises meu pecado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 7, 'Tu sabes que eu não sou mau; todavia ninguém há que [me] livre de tua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 8, 'Tuas mãos me fizeram e me formaram por completo; porém agora tu me destróis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 9, 'Por favor, lembra-te que me preparaste como o barro; e me farás voltar ao pó da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 10, 'Por acaso não me derramaste como o leite, e como o queijo me coalhaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 11, 'De pele e carne tu me vestiste; e de ossos e nervos tu me teceste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 12, 'Vida e misericórdia me concedeste, e teu cuidado guardou meu espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 13, 'Porém estas coisas escondeste em teu coração; eu sei que isto esteve contigo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 14, 'Se eu pecar, tu me observarás, e não absolverás minha culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 15, 'Se eu for perverso, ai de mim! Mesmo se eu for justo, não levantarei minha cabeça; estou farto de desonra, e de ver minha aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 16, 'Se [minha cabeça] se exaltar, tu me caças como um leão feroz, e voltas a fazer em coisas extraordinárias contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 17, 'Renovas tuas testemunhas contra mim, e multiplicas tua ira sobre mim; combates vêm sucessivamente contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 18, 'Por que me tiraste da madre? [Bom seria] se eu não tivesse respirado, e nenhum olho me visse!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 19, 'Teria sido como se nunca tivesse existido, e desde o ventre [materno] seria levado à sepultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 20, 'Por acaso não são poucos os meus dias? Cessa [pois] e deixa-me, para que eu tenha um pouco de alívio,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 21, 'Antes que eu me vá para não voltar, à terra da escuridão e da sombra de morte;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 10, 22, 'Terra escura ao extremo, tenebrosa, sombra de morte, sem ordem alguma, onde a luz é como a escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 1, 'Então Zofar, o naamita, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 2, 'Por acaso a multidão de palavras não seria respondida? E o homem falador teria razão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 3, 'Por acaso tuas palavras tolas faria as pessoas se calarem? E zombarias tu, e ninguém te envergonharia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 4, 'Pois disseste: Minha doutrina é pura, e eu sou limpo diante de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 5, 'Mas na verdade, queria eu que Deus falasse, e abrisse seus lábios contra ti,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 6, 'E te fizesse saber os segredos da sabedoria, porque o verdadeiro conhecimento tem dois lados; por isso sabe tu que Deus tem te castigado menos que [mereces] por tua perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 7, 'Podes tu compreender os mistérios de Deus? Chegarás tu à perfeição do Todo-Poderoso?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 8, '[Sua sabedoria] é mais alta que os céus; que tu poderás fazer? E mais profunda que o Xeol; que tu poderás conhecer?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 9, 'Sua medida é mais comprida que a terra, e mais larga que o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 10, 'Se ele passar, e prender, ou se ajuntar [para o julgamento] ,quem poderá o impedir?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 11, 'Pois ele conhece as pessoas vãs, e vê a maldade; por acaso ele não a consideraria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 12, 'O homem tolo se tornará entendido quando do asno selvagem nascer um humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 13, 'Se tu preparares o teu coração, e estenderes a ele tuas mãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 14, 'Se alguma maldade houver em tua mão, lança-a de ti, e não deixes a injustiça habitar em tuas tendas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 15, 'Então levantarás teu rosto sem mácula; estarás firme, e não temerás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 16, 'E esquecerás teu sofrimento, [ou] lembrarás dele como de águas que já passaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 17, 'E [tua] vida será mais clara que o meio-dia; ainda que haja trevas, tu serás como o amanhecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 18, 'E serás confiante, porque haverá esperança; olharás em redor, [e] repousarás seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 19, 'E te deitarás, e ninguém te causará medo; e muitos suplicarão a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 11, 20, 'Porém os olhos dos maus se enfraquecerão, e o refúgio deles perecerá; a esperança deles será a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 1, 'Porém Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 2, 'Verdadeiramente vós sois o povo; e convosco morrerá a sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 3, 'Também eu tenho entendimento como vós; e não sou inferior a vós; e quem há que não saiba coisas como essas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 4, 'Eu sou o motivo de riso de meus amigos, eu que invocava a Deus, e ele me respondia; o justo e íntegro serve de riso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 5, 'Na opinião de quem está descansado, a desgraça é desprezada, [como se] estivesse preparada aos que cujos pés escorregam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 6, 'As tendas dos ladrões têm descanso, e os que irritam a Deus estão seguros; os que trazem [seu] deus em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 7, 'Verdadeiramente pergunta agora aos animais, que eles te ensinarão; e às aves dos céus, que elas te explicarão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 8, 'Ou fala com a terra, que ela te ensinará; até os peixes do mar te contarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 9, 'Quem entre todas estas coisas não entende que a mão do SENHOR faz isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 10, 'Em sua mão está a alma de tudo quanto vive, e o espírito de toda carne humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 11, 'Por acaso o ouvido não distingue as palavras, e o paladar prova as comidas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 12, 'Nos velhos está o conhecimento, e na longa idade o entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 13, 'Com [Deus] está a sabedoria e a força; o conselho e o entendimento lhe pertencem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 14, 'Eis que o que ele derruba não pode ser reconstruído; e ninguém pode libertar o homem a quem ele aprisiona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 15, 'Eis que, [quando] ele detém as águas, elas se secam; [quando] ele as deixa sair, elas transtornam a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 16, 'Com ele está a força e a sabedoria; Seu é o que erra, e o que faz errar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 17, 'Ele leva os conselheiros despojados, e faz os juízes enlouquecerem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 18, 'Ele solta a atadura dos reis, e ata um cinto a seus lombos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 19, 'Ele leva os sacerdotes despojados, e transtorna os poderosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 20, 'Ele tira a fala daqueles a quem os outros confiam, e tira o juízo dos anciãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 21, 'Ele derrama menosprezo sobre os príncipes, e afrouxa o cinto dos fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 22, 'Ele revela as profundezas das trevas, e traz a sombra de morte à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 23, 'Ele multiplica as nações, e ele as destrói; ele dispersa as nações, e as reúne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 24, 'Ele tira o entendimento dos líderes do povo da terra, e os faz vaguear pelos desertos, sem caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 12, 25, 'Nas trevas andam apalpando, sem terem luz; e os faz cambalear como a bêbados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 1, 'Eis que meus olhos têm visto tudo [isto] ; meus ouvidos o ouviram, e entenderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 2, 'Assim como vós o sabeis, eu também o sei; não sou inferior a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 3, 'Mas eu falarei com o Todo-Poderoso, e quero me defender para com Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 4, 'Pois na verdade vós sois inventores de mentiras; todos vós sois médicos inúteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 5, 'Bom seria se vos calásseis por completo, pois seria sabedoria de vossa parte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 6, 'Ouvi agora meu argumento, e prestai atenção aos argumentos de meus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 7, 'Por acaso falareis perversidade por Deus, e por ele falareis engano?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 8, 'Fareis acepção de sua pessoa? Brigareis em defesa de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 9, 'Seria bom [para vós] se ele vos investigasse? Enganareis a ele como se engana a algum homem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 10, 'Certamente ele vos repreenderá, se em oculto fizerdes acepção de pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 11, 'Por acaso a majestade dele não vos espantará? E o temor dele não cairá sobre sobre vós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 12, 'Vossos conceitos são provérbios de cinzas; vossas defesas são como defesas de lama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 13, 'Calai-vos diante de mim, e eu falarei; e venha sobre mim o que vier.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 14, 'Por que tiraria eu minha carne com meus dentes, e poria minha alma em minha mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 15, 'Eis que, ainda que ele me mate, nele esperarei; porém defenderei meus caminhos diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 16, 'Ele mesmo será minha salvação; pois o hipócrita não virá perante ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 17, 'Ouvi com atenção minhas palavras, e com vossos ouvidos minha declaração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 18, 'Eis que já tenho preparado minha causa; sei que serei considerado justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 19, 'Quem é o que brigará comigo? Pois então eu me calaria e morreria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 20, 'Somente duas coisas não faças comigo; então eu não me esconderei de teu rosto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 21, 'Afasta tua mão de sobre mim, e teu terror não me espante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 22, 'Chama, e eu responderei; ou eu falarei, e tu me responde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 23, 'Quantas culpas e pecados eu tenho? Faze-me saber minha transgressão e meu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 24, 'Por que escondes teu rosto, e me consideras teu inimigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 25, 'Por acaso quebrarás a folha arrebatada [pelo vento] ? E perseguirás a palha seca?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 26, 'Por que escreves contra mim amarguras, e me fazes herdar as transgressões de minha juventude?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 27, 'Também pões meus pés no tronco, e observas todos os meus caminhos. Tu pões limites às solas dos meus pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 13, 28, 'Eu me consumo como a podridão, como uma roupa que a traça rói.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 1, 'O homem, nascido de mulher, é curto de dias, e farto de inquietação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 2, 'Ele sai como uma flor, e é cortado; foge como a sombra, e não permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 3, 'Contudo sobre este abres teus olhos, e me trazes a juízo contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 4, 'Quem tirará algo puro do imundo? Ninguém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 5, 'Visto que seus dias já estão determinados, e contigo está o número de seus meses, tu lhe puseste limites, [dos quais] ele não passará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 6, 'Desvia-te dele, para que ele tenha repouso; até que, como o empregado, complete seu dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 7, 'Porque há [ainda] alguma esperança para a árvore que, se cortada, ainda se renove, e seus renovos não cessem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 8, 'Ainda que sua raiz se envelheça na terra, e seu tronco morra no solo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 9, 'Ao cheiro das águas ela brotará, e dará ramos como uma planta nova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 10, 'Porém o homem morre, e se abate; depois de expirar, onde ele está?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 11, 'As águas se vão do lago, e o rio se esgota, e se seca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 12, 'Assim o homem se deita, e não se levanta; até que não haja mais céus, eles não despertarão, nem se erguerão de seu sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 13, 'Ah, se tu me escondesses no Xeol, e me ocultasses até que a tua ira passasse, se me pusesses um limite de tempo, e te lembrasses de mim!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 14, 'Se o homem morrer, voltará a viver? Todos os dias de meu combate esperarei, até que venha minha dispensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 15, 'Tu [me] chamarás, e eu te responderei; e te afeiçoarás à obra de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 16, 'Pois então tu contarias meus passos, e não ficarias vigiando meu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 17, 'Minha transgressão estaria selada numa bolsa, e tu encobririas minhas perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 18, 'E assim como a montanha cai e é destruída, e a rocha muda de seu lugar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 19, 'E a água desgasta as pedras, e as enxurradas levam o pó da terra, assim também tu fazes perecer a esperança do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 20, 'Sempre prevaleces contra ele, e ele passa; tu mudas o aspecto de seu rosto, e o despedes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 21, 'Se seus filhos vierem a ter honra, ele não saberá; se forem humilhados, ele não perceberá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 14, 22, 'Ele apenas sente as dores em sua própria carne, e lamenta por sua própria alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 1, 'Então Elifaz, o temanita, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 2, 'Por acaso o sábio dará como resposta vão conhecimento, e encherá seu ventre de vento oriental?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 3, 'Repreenderá com palavras que nada servem, e com argumentos que de nada aproveitam?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 4, 'Porém tu destróis o temor, e menosprezas a oração diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 5, 'Pois tua perversidade conduz tua boca, e tu escolheste a língua dos astutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 6, 'Tua boca te condena, e não eu; e teus lábios dão testemunho contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 7, 'Por acaso foste tu o primeiro ser humano a nascer? Ou foste gerado antes dos morros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 8, 'Ouviste tu o segredo de Deus? Reténs tu [apenas] contigo a sabedoria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 9, 'O que tu sabes que nós não saibamos? [O que] tu entendes que não tenhamos [entendido] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 10, 'Entre nós também há os que tenham cabelos grisalhos, também há os que são muito mais idosos que teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 11, 'Por acaso as consolações de Deus te são poucas? As mansas palavras voltadas a ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 12, 'Por que o teu coração te arrebata, e por que centelham teus olhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 13, 'Para que vires teu espírito contra Deus, e deixes sair [tais] tais palavras de tua boca?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 14, 'O que é o homem, para que seja puro? E o nascido de mulher, para que seja justo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 15, 'Eis que [Deus] não confia em seus santos, nem os céus são puros diante de seus olhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 16, 'Quanto menos o homem, abominável e corrupto, que bebe a maldade como água?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 17, 'Escuta-me; eu te mostrarei; eu te contarei o que vi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 18, '(O que os sábios contaram, o que não foi encoberto por seus pais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 19, 'A somente os quais a terra foi dada, e estranho nenhum passou por meio deles):'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 20, 'Todos os dias do perverso são sofrimento para si, o número de anos reservados ao opressor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 21, 'Ruídos de horrores estão em seus ouvidos; até na paz lhe sobrevém o assolador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 22, 'Ele não crê que voltará da escuridão; ao contrário, a espada o espera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 23, 'Anda vagueando por comida, onde quer que ela esteja. Ele sabe que o dia das trevas está prestes a acontecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 24, 'Angústia e aflição o assombram, [e] prevalecem contra ele como um rei preparado para a batalha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 25, 'Porque ele estendeu sua mão contra Deus, e se embraveceu contra o Todo-Poderoso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 26, 'Corre contra ele com [dureza] de pescoço, e como seus escudos grossos e levantados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 27, 'Porque cobriu seu rosto com sua gordura, e engordou as laterais de seu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 28, 'E habitou em cidades desoladas cidades, em casas desabitadas; que estavam prestes a desmoronar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 29, 'Ele não enriquecerá, nem seu patrimônio subsistirá, nem suas riquezas se estenderão pela terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 30, 'Não escapará das trevas; a chama secará seus ramos, e ao sopro de sua boca desparecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 31, 'Não confie ele na ilusão para ser enganado; pois a sua recompensa será nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 32, 'Não sendo ainda seu tempo, ela se cumprirá; e seu ramo não florescerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 33, 'Sacudirá suas uvas antes de amadurecerem como a vide, e derramará sua flor como a oliveira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 34, 'Pois a ajuntamento dos hipócritas será estéril, e fogo consumirá as tendas do suborno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 15, 35, 'Eles concebem a maldade, e dão à luz a perversidade; e o ventre deles prepara enganos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 1, 'Porém Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 2, 'Ouvi muitas coisas como estas; todos vós sois consoladores miseráveis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 3, 'Por acaso terão fim as palavras de vento? Ou o que é que te provoca a responderes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 4, 'Também eu poderia falar como vós, se vossa alma estivesse no lugar da minha alma; eu poderia amontoar palavras contra vós, e contra vós sacudir minha cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 5, 'Porém eu vos confortaria com minha boca, e a consolação de meus lábios serviria para aliviar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 6, 'Ainda que eu fale, minha dor não cessa; e se eu me calar, em que me alivio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 7, 'Na verdade agora ele me tornou exausto; tu assolaste toda a minha companhia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 8, 'Testemunha [disto é] que já me enrugaste; e minha magreza já se levanta contra mim para em meu rosto dar testemunho [contra mim] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 9, 'Sua ira me despedaça, e ele me odeia; range seus dentes contra mim; meu adversário aguça seus olhos contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 10, 'Abrem sua boca contra mim; com desprezo esbofeteiam meu rosto, e todos se ajuntam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 11, 'Deus me entregou ao perverso, e me fez cair nas mãos dos malignos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 12, 'Tranquilo eu estava, porém ele me quebrantou; e pegou-me pelo pescoço, e me despedaçou; e fez de mim seu alvo de pontaria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 13, 'Seus flecheiros me cercaram-me, partiu meus rins, e não [me] poupou; meu fel derramou em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 14, 'Quebrantou-me de quebrantamento sobre quebrantamento; correu contra mim como um guerreiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 15, 'Costurei saco sobre minha pele, e revolvi minha cabeça no pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 16, 'Meu rosto está vermelho de choro, e minhas pálpebras estão escurecidas ao extremo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 17, 'Apesar de não haver injustiça em minhas mãos, e de minha oração ser pura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 18, 'Ó terra! Não cubras o meu sangue, e não haja lugar para meu clamor!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 19, 'Eis que mesmo agora minha testemunha está nos céus, e meu defensor nas alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 20, 'Meus amigos zombam de mim, [mas] meus olhos estão derramando para Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 21, 'Ah, se [fosse possível] defender a causa com Deus em favor do homem, como o filho do homem em favor de seu amigo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 16, 22, 'Pois poucos anos restam, e seguirei o caminho [por onde] não voltarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 1, 'Meu espírito está arruinado, meus dias vão se extinguindo, e a sepultura já etá pronta para mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 2, 'Comigo há ninguém além de zombadores, e meus olhos são obrigados a ficar diante de suas provocações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 3, 'Concede-me, por favor, uma garantia para comigo; quem [outro] há que me dê a mão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 4, 'Pois aos corações deles tu encobriste do entendimento; portanto não os exaltarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 5, 'Aquele que denuncia a seus amigos em proveito próprio, também os olhos de seus filhos desfalecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 6, 'Ele tem me posto por ditado de povos, e em meu rosto é onde eles cospem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 7, 'Por isso meus olhos se escureceram de mágoa, e todos os membros de meu corpo são como a sombra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 8, 'Os íntegros pasmarão sobre isto, e o inocente se levantará contra o hipócrita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 9, 'E o justo prosseguirá seu caminho, e o puro de mãos crescerá em força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 10, 'Mas, na verdade, voltai-vos todos vós, e vinde agora, pois sábio nenhum acharei entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 11, 'Meus dias se passaram, meus pensamentos foram arrancados, os desejos do meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 12, 'Tornaram a noite em dia; a luz se encurta por causa das trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 13, 'Se eu esperar, o Xeol será minha casa; nas trevas estenderei minha cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 14, 'À cova chamo: Tu és meu pai; e aos vermes: [Sois] minha mãe e minha irmã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 15, 'Onde, pois, estaria agora minha esperança? Quanto à minha esperança, quem a poderá ver?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 17, 16, 'Será que ela descerá aos ferrolhos do Xeol? Descansaremos juntos no pó da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 1, 'Então Bildade, o suíta, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 2, 'Quando é que dareis fim às palavras? Prestai atenção, e então falaremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 3, 'Por que somos considerados animais, e tolos em vossos olhos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 4, 'Ó tu, que despedaças tua alma com tua ira; será a terra abandonada por tua causa, e será movida a rocha de seu lugar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 5, 'Na verdade, a luz dos perverso se apagará, e a faísca de seu fogo não brilhará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 6, 'A luz se escurecerá em sua tenda, e sua lâmpada sobre ele se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 7, 'Os seus passos fortes serão encurtados, e seu [próprio] intento o derrubará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 8, 'Pois será lançado à rede pelos seus [próprios] pés, e sobre fios enredados andará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 9, 'Laço o pegará pelo calcanhar; a armadilha o prenderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 10, 'Uma corda lhe está escondida debaixo da terra, e uma armadilha para ele está no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 11, 'Assombros o espantarão ao redor, e o farão correr por onde seus passos forem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 12, 'Sua força se tornará em fome, e a perdição está pronta ao seu lado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 13, 'Partes de sua pele serão consumidas; o primogênito da morte devorará os membros de seu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 14, 'Será arrancado de sua tenda em que confiava, e será levado ao rei dos assombros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 15, 'Em sua tenda morará o que não é seu; enxofre se espalhará sobre a sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 16, 'Por debaixo suas raízes se secarão, e por cima seus ramos serão cortados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 17, 'Sua memória perecerá da terra, e não terá nome pelas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 18, 'Será lançado da luz para as trevas, e expulso será do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 19, 'Não terá filho nem neto entre seu povo, nem sobrevivente em suas moradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 20, 'Os do ocidente se espantarão com o seu dia, e os do oriente ficarão horrorizados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 18, 21, 'Assim são as moradas do perverso, e este é o lugar [daquele que] não reconhece a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 1, 'Porém Jó respondeu dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 2, 'Até quando atormentareis minha alma, e me quebrantareis com palavras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 3, 'Já dez vezes me humilhastes; não tendes vergonha em me maltratar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 4, 'Mesmo se eu tiver errado, meu erro cabe apenas a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 5, 'Visto que vos exaltais contra mim, e contra mim usais minha desgraça,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 6, 'Sabei, pois, que foi Deus que me transtornou, e [com] sua rede me cercou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 7, 'Eis que eu clamo: Violência! Porém não sou respondido; grito, porém não há justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 8, 'Ele entrincheirou meu caminho, de modo que não consigo passar; e pôs trevas sobre minhas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 9, 'Ele me despojou de minha honra, e tirou a coroa de minha cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 10, 'Ele me derrubou por todos os lados, e pereço; e arrancou minha esperança como a uma árvore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 11, 'E fez inflamar contra mim sua ira, e me considerou para consigo como a [um de] seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 12, 'Juntas vieram suas tropas; prepararam contra mim seu caminho, e se acamparam ao redor de minha tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 13, 'Ele afastou meus irmãos para longe de mim; e os que me conheciam agora me estranham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 14, 'Meus parentes [me] deixaram, e meus conhecidos se esqueceram de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 15, 'Os moradores de minha casa e minhas servas me tiveram por estranho; estrangeiro me tornei em seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 16, 'Chamei a meu servo, e ele não respondeu; de minha própria boca eu lhe suplicava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 17, 'Meu hálito é estranho à minha mulher, e sou repugnante aos filhos de minha mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 18, 'Até os meninos me desprezam; quando eu me levanto, falam contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 19, 'Todos os meus amigos próximos me abominam; e [até] aqueles que eu amava se viraram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 20, 'Meus ossos se grudaram à minha pele e à minha carne; e escapei [só] com a pele de meus dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 21, 'Compadecei-vos de mim, meus amigos, compadecei-vos de mim; pois a mão de Deus me tocou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 22, 'Por que vós me perseguis como Deus, e não vos fartais de minhas carne?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 23, 'Ah se minhas palavras fossem escritas! Ah se fossem escritas em um livro!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 24, 'Que com ponta de ferro e com chumbo fossem esculpidas em pedra para sempre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 25, 'Pois eu sei que meu Redentor vive, e ao fim se levantará sobre a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 26, 'E mesmo depois de consumida minha pele, então em minha carne verei a Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 27, 'Ao qual eu verei para mim, e meus olhos [o] verão, e não outro. [Isto é o que] minhas entranhas anseiam dentro de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 28, 'Se disserdes: Como o perseguiremos? Pois a raiz do problema se acha em mim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 19, 29, 'Temei vós mesmos a espada; pois furor [há nos] castigos pela espada; para que [assim] saibais que [haverá] julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 1, 'E Zofar, o naamita, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 2, 'Por isso meus meus pensamentos me fazem responder; por causa da agitação dentro de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 3, 'Eu ouvi a repreensão que me envergonha; mas o espírito desde o meu entendimento responderá por mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 4, 'Por acaso não sabes isto, [que foi] desde a antiguidade, desde que o ser humano foi posto no mundo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 5, 'Que o júbilo dos perversos é breve, e a alegria do hipócrita [dura apenas] um momento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 6, 'Ainda que sua altura subisse até o céu, e sua cabeça chegasse até as nuvens,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 7, '[Mesmo assim] com o seu excremento perecerá para sempre; os que houverem o visto, dirão: Onde ele está?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 8, 'Como um sonho voará, e não será achado; e será afugentado como a visão noturna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 9, 'O olho que já o viu nunca mais o verá; nem seu lugar olhará mais para ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 10, 'Seus filhos procurarão o favor dos pobres; e suas mãos devolverão a sua riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 11, 'Seus ossos estão cheios de sua juventude, que juntamente com ele se deitará no pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 12, 'Se o mal é doce em sua boca, e o esconde debaixo de sua língua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 13, 'Se o guarda para si, e não o abandona; ao contrário, o retém em sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 14, 'Sua comida se mudará em suas entranhas, veneno de cobras será em seu interior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 15, 'Engoliu riquezas, porém as vomitará; Deus as tirará de seu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 16, 'Veneno de cobras subará; língua de víbora o matará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 17, 'Não verá correntes, rios, [e] ribeiros de mel e de manteiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 18, 'Restituirá o trabalho e não o engolirá; da riqueza de seu comério não desfrutará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 19, 'Pois oprimiu [e] desamparou aos pobres; roubou a casa que não edificou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 20, 'Por não ter sentido sossego em seu ventre, nada preservará de sua tão desejada riqueza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 21, 'Nada [lhe] restou para que devorasse; por isso sua riqueza não será duradoura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 22, 'Estando cheio de sua fartura, [ainda] estará angustiado; todo o poder da miséria virá sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 23, 'Quando ele estiver enchendo seu vendre, Deus mandará sobre ele o ardor de sua ira, e [a] choverá sobre ele em sua comida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 24, '[Ainda que] fuja das armas de ferro, o arco de bronze o atravessará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 25, 'Ele a tirará de [seu] corpo, e a ponta brilhante atingirá seu fígado; haverá sobre ele assombros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 26, 'Todas as trevas estão reservadas para seus tesouros escondidos; um fogo não assoprado o consumirá; acabará com o que restar em sua tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 27, 'Os céus revelarão sua maldade, e a terra se levantará contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 28, 'As riquezas de sua casa serão transportadas; nos dias de sua ira elas se derramarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 20, 29, 'Esta é a parte que Deus dá ao homem perverso, a herança que Deus lhe prepara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 1, 'Porém Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 2, 'Ouvi atentamente minhas palavras, e seja isto vossas consolações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 3, 'Suportai-me, e eu falarei; e depois de eu ter falado, [então] zombai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 4, 'Por acaso eu me queixo de algum ser humano? Porém ainda que [assim fosse] ,por que meu espírito não se angustiaria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 5, 'Olhai-me, e espantai-vos; e ponde a mão sobre a boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 6, 'Pois quando eu me lembro [disto] ,me assombro, e minha carne é tomada de tremor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 7, 'Por que razão os perversos vivem, envelhecem, e ainda crescem em poder?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 8, 'Seus filhos progridem com eles diante de seus rostos; e seus descendentes diante de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 9, 'Suas casas têm paz, sem temor, e a vara de Deus não está contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 10, 'Seus touros procriam, e não falham; suas vacas geram filhotes, e não abortam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 11, 'Suas crianças saem como um rebanho, e seus filhos saem dançando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 12, 'Levantam [a voz] ao [som] de tamboril e de harpa e se alegram ao som de flauta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 13, 'Em prosperidade gastam seus dias, e em um momento descem ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 14, 'Assim dizem a Deus: Afasta-te de nós, porque não queremos conhecer teus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 15, 'Quem é o Todo-Poderoso, para que o sirvamos? E de que nos aproveitará que oremos a ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 16, 'Eis que sua prosperidade não se deve às mãos deles. Longe de mim esteja o conselho dos perversos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 17, 'Quantas vezes sucede que a lâmpada dos perversos se apaga, e sua perdição vem sobre eles, [e] Deus em sua ira [lhes] reparte dores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 18, 'Eles serão como palha diante do vento, como o restos de palha que o turbilhão arrebata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 19, '[Vós dizeis] : Deus guarda sua violência para seus filhos. Que [Deus] pague ao próprio [perverso] ,para que o conheça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 20, 'Seus olhos vejam sua ruína, e beba da ira do Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 21, 'Pois que interesse teria ele em sua casa depois de si, quando o número for cortado o número de seus meses?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 22, 'Poderia alguém ensinar conhecimento a Deus, que julga [até] os que estão no alto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 23, 'Alguém morre na sua força plena, estando todo tranquilo e próspero,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 24, 'Seus baldes estando cheios de leite, e o tutano de seus ossos umedecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 25, 'Porém outro morre com amargura de alma, nunca tendo experimentado a prosperidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 26, 'Juntamente jazem no pó, e os vermes os cobrem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 27, 'Eis que eu sei vossos pensamentos, e os mais intentos que planejais contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 28, 'Porque dizeis: Onde está a casa do príncipe?, e: Onde está tenda das moradas dos perversos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 29, 'Por acaso não perguntastes aos que passam pelo caminho, e não conheceis seus sinais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 30, 'Que os maus são preservados no dia da destruição, [e] são livrados no dia das fúrias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 31, 'Quem lhe denunciará seu caminho em sua face? E quem lhe pagará pelo que ele fez?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 32, 'Finalmente ele é levado à sepultura, e no túmulo fazem vigilância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 33, 'Os torrões do vale lhe são doces; e todos o seguem; e adiante dele estão inúmeros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 21, 34, 'Como, pois, me consolais em vão, já que vossas em vossas respostas [só] resta falsidade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 1, 'Então Elifaz, o temanita, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 2, 'Por acaso o homem será de [algum] proveito a Deus? Pode ele se beneficiar de algum sábio?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 3, 'É útil ao Todo-Poderoso que sejas justo? Ganha ele algo se os teus caminhos forem íntegros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 4, 'Acaso ele te repreende [e] vem contigo a juízo por causa da tua reverência?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 5, '[Ou] não será por causa de tua grande malícia, e de tuas maldades que não têm fim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 6, 'Porque tomaste penhor a teus irmãos sem causa, e foste tu que tiraste as roupas dos nus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 7, 'Não deste de beber água ao cansado, e negaste o pão ao faminto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 8, 'Porém o homem poderoso teve a terra; e o homem influente habitava nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 9, 'Às viúvas despediste vazias, e os braços dos órfãos foram quebrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 10, 'Por isso que há laços ao redor de ti, e espanto repentino te perturbou;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 11, 'Ou trevas, para que não vejas; e inundação de água te cobre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 12, 'Por acaso Deus não está na altura dos céus? Olha, pois, para o cume das estrelas, como estão elevadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 13, 'Porém tu dizes: O que Deus sabe? Como ele julgará por entre a escuridão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 14, 'As nuvens são seu esconderijo, e ele não vê; ele passeia pela abóbada do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 15, 'Por acaso deste atenção para o velho caminho que pisaram os homens injustos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 16, 'Tais foram cortados antes de tempo; [sobre] o fundamento deles foi derramada uma enchente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 17, 'Eles diziam a Deus: Afasta-te de nós! O que o Todo-Poderoso pode fazer por nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 18, 'Sendo ele o que havia enchido suas casas de bens. Seja, porém, longe de mim o conselho dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 19, 'Os justos virão e se alegrarão; e o inocente os escarnecerá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 20, '[Dizendo] : Certamente nossos adversários foram destruídos, e o que sobrou deles o fogo consumiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 21, 'Reconcilia-te, pois, com [Deus] ,e terás paz; assim o bem virá a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 22, 'Aceita, pois, a instrução de sua boca, e põe suas palavras em teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 23, 'Se te converteres ao Todo-Poderoso, serás edificado; se afastares a maldade de tua tenda,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 24, 'E lançares [teu] ouro no pó, o [ouro] de Ofir junto às rochas dos ribeiros,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 25, 'Então o próprio Todo-Poderoso será teu ouro, e tua prata maciça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 26, 'Porque então te deleitarás no Todo-Poderoso, e levantarás teu rosto a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 27, 'Orarás a ele, e ele te ouvirá; e tu [lhe] pagarás teus votos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 28, 'Aquilo que tu determinares se cumprirá a ti, e em teus caminhos a luz brilhará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 29, 'Quando [alguém] for abatido, e tu disseres: Haja exaltação, Então [Deus] salvará ao humilde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 22, 30, 'Ele libertará até ao que não é inocente, que será livrado pela pureza de tuas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 1, 'Porém Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 2, 'Até hoje minha queixa é uma amargura; a mão [de Deus] sobre mim é mais pesada que meu gemido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 3, 'Ah se eu soubesse como poderia achá-lo! [Então] eu me chegaria até seu trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 4, 'Apresentaria minha causa diante dele, e encheria minha boca de argumentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 5, 'Eu saberia as palavras que ele me responderia, e entenderia o que me diria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 6, 'Por acaso ele brigaria comigo com seu grande poder? Não, pelo contrário, ele me daria atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 7, 'Ali o íntegro pleitearia com ele, e eu me livraria para sempre de meu Juiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 8, 'Eis que se eu for ao oriente, ele não está ali; [se for] ao ocidente, e não o percebo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 9, 'Se ao norte ele opera, eu não [o] vejo; se ele se esconde ao sul, não [o] enxergo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 10, 'Porém ele conhece meu caminho: Provar-me-á, e sairei como ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 11, 'Meus pés seguiram seus passos; guardei seu caminho, e não me desviei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 12, 'Nunca retirei [de mim] o preceito de seus lábios, e guardei as palavras de sua boca mais que minha porção [de comida] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 13, 'Porém se ele está decidido, quem poderá o desviar? O que sua alma quiser, isso fará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 14, 'Pois ele cumprirá o que está determinado para mim; ele [ainda] tem muitas coisas como estas consigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 15, 'Por isso eu me perturbo em sua presença. Quando considero [isto] ,tenho medo dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 16, 'Deus enfraqueceu meu coração; o Todo-Poderoso tem me perturbado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 23, 17, 'Pois não estou destruído por causa das trevas, nem por causa da escuridão que encobriu meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 1, 'Por que os tempos não são marcados pelo Todo-Poderoso? Por que os que o conhecem não veem seus dias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 2, 'Há os que mudam os limites de lugar, roubam rebanhos, e os apascentam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 3, 'Levam o asno do órfão; penhoram o boi da viúva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 4, 'Desviam do caminho aos necessitados; os pobres da terra juntos se escondem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 5, 'Eis que como asnos selvagens no deserto eles saem a seu trabalho buscando insistentemente por comida; o deserto dá alimento a ele [e a seus] filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 6, 'No campo colhem sua forragem, e vindimam a vinha do perverso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 7, 'Passam a noite nus, por falta de roupa; sem terem coberta contra o frio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 8, 'Pelas correntes das montanhas são molhados e, não tendo abrigo, abraçam-se às rochas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 9, '[Há os que] arrancam ao órfão do peito, e do pobre tomam penhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 10, 'Ao nus fazem andar sem vestes, e fazem os famintos carregarem feixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 11, 'Entre suas paredes espremem o azeite; pisam nas prensas de uvas, e [ainda] têm sede.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 12, 'Desde a cidade as pessoas gemem, e as almas dos feridos clamam; Mas Deus não dá atenção ao erro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 13, 'Há os que se opõem à luz; não conhecem seus caminhos, nem permanecem em suas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 14, 'De manhã o homicida se levanta, mata ao pobre e ao necessitado, e de noite ele age como ladrão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 15, 'O olho do adúltero aguarda o crepúsculo, dizendo: Olho nenhum me verá; E esconde seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 16, 'Nas trevas vasculham as casas, de dia eles se trancam; não conhecem a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 17, 'Porque a manhã é para todos eles como sombra de morte; pois são conhecidos dos pavores de sombra de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 18, 'Ele é ligeiro sobre a superfície das águas; maldita é sua porção sobre a terra; não se vira para o caminho das vinhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 19, 'A seca e o calor desfazem as águas da neve; assim [faz] o Xeol aos que pecaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 20, 'A mãe se esquecerá dele; doce será para os vermes; nunca mais haverá memória [dele] , e a perversidade será quebrada como um árvore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 21, 'Aflige à mulher estéril, [que] não dá à luz; e nenhum bem faz à viúva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 22, 'Mas [Deus] arranca aos poderosos com seu poder; [quando] Deus se levanta, não há vida segura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 23, 'Se ele lhes dá descanso, nisso confiam; [mas] os olhos de [Deus] estão [postos] nos caminhos deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 24, 'São exaltados por um pouco [de tempo] ,mas [logo] desaparecem; são abatidos, encerrados como todos, e cortados como cabeças das espigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 24, 25, 'Se não é assim, quem me desmentirá, ou anulará minhas palavras?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 1, 'Então Bildade, o suíta, respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 2, 'O domínio e o temor estão com ele; ele faz paz em suas alturas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 3, 'Por acaso suas tropas têm número? E sobre quem não se levanta sua luz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 4, 'Como, pois, o ser humano seria justo para com Deus? E como seria puro aquele que nasce de mulher?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 5, 'Eis que até a luz não tem brilho; nem as estrelas são puras diante de seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 25, 6, 'Quanto menos o ser humano, que é uma larva, e o filho de homem, que é um verme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 1, 'Porém Jó respondeu, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 2, 'Como tende ajudado ao que não tem força, [e] sustentado ao braço sem vigor!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 3, 'Como tende aconselhado ao que não tem conhecimento, e [lhe] explicaste detalhadamente a verdadeira causa!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 4, 'A quem tens dito [tais] palavras? E de quem é o espírito que sai de ti?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 5, 'Os mortos tremem debaixo das águas com os seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 6, 'O Xeol está nu perante Deus , e não há cobertura para a perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 7, 'Ele estende o norte sobre o vazio, suspende a terra sobre o nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 8, 'Ele amarra as águas em suas nuvens, todavia a nuvem não se rasga debaixo dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 9, 'Ele encobre a face de seu trono, e sobre ele estende sua nuvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 10, 'Ele determinou limite à superfície das águas, até a fronteira entre a luz e as trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 11, 'As colunas do céu tremem, e se espantam por sua repreensão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 12, 'Ele agita o mar com seu poder, e com seu entendimento fere abate a Raabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 13, 'Por seu Espírito adornou os céus; sua mão perfurou a serpente veloz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 26, 14, 'Eis que estas são [somente] as bordas de seus caminhos; e quão pouco é o que temos ouvido dele! Quem, pois, entenderia o trovão de seu poder?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 1, 'E Jó prosseguiu em falar seu discurso, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 2, 'Vive Deus, que tirou meu direito, o Todo-Poderoso, que amargou minha alma,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 3, 'Que enquanto meu fôlego estiver em mim, e o sopro de Deus em minhas narinas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 4, 'Meus lábios não falarão injustiça, nem minha língua pronunciará engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 5, 'Nunca aconteça que eu diga que vós estais certos; até eu morrer nunca tirarei de mim minha integridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 6, 'Eu me apegarei à minha justiça, e não a deixarei ir; meu coração não terá de que me acusar enquanto eu viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 7, 'Seja meu inimigo como o perverso, e o que se levantar contra mim como o injusto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 8, 'Pois qual é a esperança do hipócrita quando ele for cortado, quando Deus arrancar sua alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 9, 'Por acaso Deus ouvirá seu clamor quando a aflição vier sobre ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 10, 'Ele se deleitará no Todo-Poderoso? Invocará a Deus a todo tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 11, 'Eu vos ensinarei acerca da mão de Deus; não esconderei o que há com o Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 12, 'Eis que todos vós tendes visto [isso] ; então por que vos deixais enganar por ilusão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 13, 'Esta é a porção do homem perverso para com Deus, a herança que os violentos receberão do Todo-Poderoso:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 14, 'Se seus filhos se multiplicarem, serão para a espada; e seus descendentes não se fartarão de pão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 15, 'Os que lhe restarem, pela praga serão sepultados; e suas viúvas não chorarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 16, 'Se ele amontoar prata como o pó da terra, e se preparar roupas como lama,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 17, 'Mesmo ele tendo preparado, é o justo que se vestirá, e o inocente repartirá a prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 18, 'Jó', 'Jó', 27, 18, 'Ele constrói sua casa como a traça, como uma barraca feita por um vigilante.')
